   "a": {
    "unit_id": "BLLD_45-2019.D176.K1.c",
    "tieu_de_dieu": "Quyền của thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở",
    "khoan_cha": "Thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở có quyền sau đây:",
    "chu_don_vi": "Được sử dụng thời gian làm việc theo quy định tại khoản 2 và khoản 3 Điều này để thực hiện công việc của tổ chức đại diện người lao động tại cơ sở mà vẫn được người sử dụng lao động trả lương;"
   },
   "b": {
    "unit_id": "BLLD_45-2019.D207.K2",
    "tieu_de_dieu": "Tiền lương và các quyền lợi hợp pháp khác của người lao động trong thời gian đình công",
    "khoan_cha": "",
    "chu_don_vi": "Người lao động tham gia đình công không được trả lương và các quyền lợi khác theo quy định của pháp luật, trừ trường hợp các bên có thỏa thuận khác."
   },
   "vi_tu_chung": [
    "receive_wage"
   ]
  },
  {
   "cap_id": "P0531",
   "a": {
    "unit_id": "BLLD_45-2019.D177.K3",
    "tieu_de_dieu": "Nghĩa vụ của người sử dụng lao động đối với tổ chức đại diện người lao động tại cơ sở",
    "khoan_cha": "",
    "chu_don_vi": "Phải thỏa thuận bằng văn bản với ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở khi đơn phương chấm dứt hợp đồng lao động, chuyển làm công việc khác, kỷ luật sa thải đối với người lao động là thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở. Trường hợp không thỏa thuận được, hai bên phải báo cáo với cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh. Sau 30 ngày kể từ ngày báo cho cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh biết, người sử dụng lao động mới có quyền quyết định. Trường hợp không nhất trí với quyết định của người sử dụng lao động thì người lao động, ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở có quyền yêu cầu giải quyết tranh chấp lao động theo trình tự, thủ tục do pháp luật quy định."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D185.K4",
    "tieu_de_dieu": "Hội đồng trọng tài lao động",
    "khoan_cha": "",
    "chu_don_vi": "Khi có yêu cầu giải quyết tranh chấp lao động theo quy định tại các điều 189, 193 và 197 của Bộ luật này, Hội đồng trọng tài lao động quyết định thành lập Ban trọng tài lao động để giải quyết tranh chấp như sau:",
    "cac_muc_con": [
     "Đại diện mỗi bên tranh chấp chọn 01 trọng tài viên trong số danh sách trọng tài viên lao động;",
     "Trọng tài viên lao động do các bên lựa chọn theo quy định tại điểm a khoản này thống nhất lựa chọn 01 trọng tài viên lao động khác làm Trưởng Ban trọng tài lao động;",
     "Trường hợp các bên tranh chấp cùng lựa chọn một trọng tài viên để giải quyết tranh chấp lao động thì Ban trọng tài lao động chỉ gồm 01 trọng tài viên lao động đã được lựa chọn."
    ]
